input.command:
sudo tee /etc/docker/daemon.json <<'EOF'
{
  "log-driver": "json-file",
  "log-opts": { "max-size": "50m", "max-file": "3" }
}
EOF

sudo tee /etc/apt/apt.conf.d/99acme-proxy <<'EOF'
Acquire::http::Proxy "http://proxy.acme.internal:3128";
EOF

sudo tee /etc/nginx/sites-available/acme <<'EOF'
server {
  listen 80;
  server_name acme.internal;
  location / { proxy_pass http://127.0.0.1:3000; }
}
EOF
sudo ln -sf /etc/nginx/sites-available/acme /etc/nginx/sites-enabled/acme

input.content:
server {
    listen 80;
    server_name acme.internal;
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
    }
}
